args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film1 { dbr:Traces_of_a_Dragon dbr:Moonnupookkal }
  VALUES ?film2 { dbr:Traces_of_a_Dragon dbr:Moonnupookkal }
  FILTER (?film1 != ?film2)
  ?film1 dbo:director ?d1 .
  ?film2 dbo:director ?d2 .
  ?d1 dbo:birthDate ?bd1 .
  ?d2 dbo:birthDate ?bd2 .
  FILTER (?bd1 > ?bd2)
  BIND(?film1 AS ?film)
  BIND(?d1 AS ?director)
  BIND(?bd1 AS ?birthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = 'en') }
}

